<?= view('partials/admin_sidebar',['active'=>'attendance']) ?>
<main class="admin-main"><header class="admin-topbar"><div><span class="eyebrow accent">DATE-WISE ATTENDANCE</span><h1>Participant entry roster</h1><p>Separate complete participants by event, date and entry status.</p></div></header><?= view('partials/flash') ?>
  <section class="admin-panel"><form class="admin-filters roster-filter" method="get" action="<?= base_url('admin/attendance') ?>" data-testid="attendance-filter-form"><label>Date<input type="date" name="date" value="<?= esc($selectedDate) ?>" data-testid="attendance-date"></label><label>Event<select name="event_id" data-testid="attendance-event"><option value="0">All events</option><?php foreach($events as $event): ?><option value="<?= $event['id'] ?>" <?= $selectedEvent==(int)$event['id']?'selected':'' ?>><?= esc($event['name']) ?></option><?php endforeach ?></select></label><label>Status<select name="status" data-testid="attendance-status"><option value="all">All participants</option><option value="entered" <?= $selectedStatus==='entered'?'selected':'' ?>>Entered</option><option value="not_entered" <?= $selectedStatus==='not_entered'?'selected':'' ?>>Not entered</option></select></label><button class="button button-yellow" type="submit" data-testid="attendance-apply">Apply filters</button></form><div class="admin-kpis"><div><span>EXPECTED</span><strong data-testid="attendance-total"><?= $summary['total'] ?></strong></div><div><span>ENTERED</span><strong data-testid="attendance-entered"><?= $summary['entered'] ?></strong></div><div><span>NOT ENTERED</span><strong data-testid="attendance-not-entered"><?= $summary['not_entered'] ?></strong></div></div></section>
  <section class="admin-panel"><div class="admin-panel-heading"><div><span class="eyebrow">PARTICIPANT LIST</span><h2><?= esc($selectedDate) ?></h2></div></div><div class="table-wrap"><table><thead><tr><th>Participant</th><th>Registration</th><th>Event / day</th><th>Institute</th><th>Contact</th><th>Entry</th></tr></thead><tbody><?php foreach($roster as $row): ?><tr data-testid="attendance-roster-row-<?= esc($row['registration_id']) ?>"><td><strong><?= esc($row['participant_name']) ?></strong></td><td><?= esc($row['registration_id']) ?></td><td><?= esc($row['event_name']) ?><small><?= esc($row['event_day_label']) ?> · <?= esc($row['event_date']) ?></small></td><td><?= esc($row['college']) ?></td><td><?= esc($row['mobile']) ?><small><?= esc($row['email']) ?></small></td><td><span class="status <?= $row['entry_time']?'status-live':'status-registration-closed' ?>"><?= $row['entry_time']?'ENTERED':'NOT ENTERED' ?></span><?php if($row['entry_time']): ?><small><?= esc($row['entry_time']) ?> · <?= esc($row['scanner_name']??'Scanner') ?></small><?php endif ?></td></tr><?php endforeach ?></tbody></table><?php if(!$roster): ?><p class="empty-state" data-testid="attendance-empty">No participants match this date and filter.</p><?php endif ?></div></section>
  <section class="admin-panel"><div class="admin-panel-heading"><div><span class="eyebrow">RECENT DECISIONS</span><h2>Scan attempts</h2></div></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>Participant</th><th>Event / day</th><th>Scanner</th><th>Status</th><th>Reason</th></tr></thead><tbody><?php foreach($entries as $entry): ?><tr><td><?= esc($entry['attempted_at']) ?></td><td><?= esc($entry['participant_name']??'Unknown QR') ?><small><?= esc($entry['registration_id']??'') ?></small></td><td><?= esc($entry['event_name']??'—') ?><small><?= esc($entry['day_label']??'') ?></small></td><td><?= esc($entry['scanner_name']??'—') ?></td><td><span class="status status-<?= esc($entry['status']) ?>"><?= strtoupper(esc($entry['status'])) ?></span></td><td><?= esc($entry['reason']) ?></td></tr><?php endforeach ?></tbody></table></div></section>
</main>